export async function signIn(page, email, password) {
    await page.getByRole("textbox", { name: "Email" }).fill(email);
    await page.getByRole("textbox", { name: "Password" }).fill(password);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/auth/login**");
    await page.getByRole("button", { name: "Sign In" }).click();
    const response = await responsePromise;
    // Wait for network activities to finish
    await page.waitForTimeout(3000);
    return response;
}

export async function createCollection(page, collectionName) {
    await page.getByRole("textbox", { name: "A unique table name..." }).fill(collectionName);
    await page.getByRole("button", { name: "arrow_forward" }).click();
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/collections**");
    await page.getByRole("button", { name: "check" }).click();
    const response = await responsePromise;
    return response;
}

export async function hideCollectionInApp(page) {
    await page.getByRole("checkbox", { name: "check_box_outline_blank Hide" }).click();
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/collections/**");
    await page.getByRole("button", { name: "check" }).click();
    const response = await responsePromise;
    // Wait for network activities to finish
    await page.waitForTimeout(3000);
    return response;
}

export async function deleteCollection(page) {
    await page.getByRole("button", { name: "delete" }).click();
    await page.getByRole("button", { exact: true, name: "Delete" }).click();
}
